import 'dart:convert';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
class SessionUser { final String id,login,displayName,role; final int level; final List<String> badges; final String? phoneE164; const SessionUser({required this.id,required this.login,required this.displayName,required this.role,required this.level,required this.badges,this.phoneE164}); factory SessionUser.fromJson(Map<String,dynamic> json){final p=json['profile'] is Map?Map<String,dynamic>.from(json['profile'] as Map):const <String,dynamic>{};return SessionUser(id:'${json['id']??''}',login:'${json['username']??json['login']??''}',displayName:'${p['displayName']??json['displayName']??json['name']??''}',role:'${json['role']??'USER'}',level:(p['level'] as num?)?.toInt()??(json['level'] as num?)?.toInt()??1,badges:(p['badges'] as List???json['badges'] as List???const[]).map((e)=>'$e').toList(),phoneE164:json['phoneE164']?.toString());} Map<String,dynamic> toJson()=>{'id':id,'login':login,'displayName':displayName,'role':role,'level':level,'badges':badges,'phoneE164':phoneE164}; }
class SessionService { static const _s=FlutterSecureStorage(aOptions:AndroidOptions(encryptedSharedPreferences:true)); static const _a='lymix.auth.accessToken',_r='lymix.auth.refreshToken',_u='lymix.auth.user',_sid='lymix.auth.sessionId'; static Future<void> save({required String accessToken,required String refreshToken,required SessionUser user,String? sessionId})=>Future.wait([_s.write(key:_a,value:accessToken),_s.write(key:_r,value:refreshToken),_s.write(key:_u,value:jsonEncode(user.toJson())),if(sessionId!=null)_s.write(key:_sid,value:sessionId)]); static Future<void> updateTokens({required String accessToken,required String refreshToken,String? sessionId,SessionUser? user})=>Future.wait([_s.write(key:_a,value:accessToken),_s.write(key:_r,value:refreshToken),if(sessionId!=null)_s.write(key:_sid,value:sessionId),if(user!=null)_s.write(key:_u,value:jsonEncode(user.toJson()))]); static Future<String?> token()=>_s.read(key:_a); static Future<String?> refreshToken()=>_s.read(key:_r); static Future<String?> sessionId()=>_s.read(key:_sid); static Future<SessionUser?> user() async{final raw=await _s.read(key:_u);if(raw==null||raw.isEmpty)return null;try{return SessionUser.fromJson(Map<String,dynamic>.from(jsonDecode(raw) as Map));}catch(_){return null;}} static Future<bool> hasSession() async=>(await refreshToken())?.isNotEmpty??false; static Future<void> clear()=>Future.wait([_s.delete(key:_a),_s.delete(key:_r),_s.delete(key:_u),_s.delete(key:_sid)]); }
